UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Gelecekte BELİRLİ bir anda bir eylemin HALA SÜRMEKTE olacağı anlatılıyorsa [[q]]future continuous[[/q]] ([[q]]will be + -ing[[/q]]), [[q]]\"by\"[[/q]] + bir zamandan ÖNCE eylemin TAMAMLANMIŞ olacağı anlatılıyorsa [[q]]future perfect[[/q]] ([[q]]will have + V3[[/q]]) kullanılır:", "items": [{"heading": "Future Continuous: O Anda Sürüyor", "badge": "will be + -ing", "body": [{"type": "text", "text": "Cümlede gelecekteki BELİRLİ bir ana ([[amber]]\"at 9 PM tomorrow\", \"this time next week\"[[/amber]]) işaret edilip o anda bir eylemin HALA SÜRMEKTE olacağı anlatılıyorsa [[q]]future continuous[[/q]] ([[q]]will be + -ing[[/q]]) kullanılır ([[q]]\"At 9 PM, I will be flying to Istanbul\"[[/q]] = o saatte uçakta olacağım, eylem sürüyor)."}]}, {"heading": "Future Perfect: O Zamandan Önce Bitmiş", "badge": "will have + V3", "body": [{"type": "text", "text": "Cümlede [[q]]\"by\"[[/q]] + gelecek zaman ifadesi ([[amber]]\"by next year\", \"by the time she arrives\"[[/amber]]) varsa ve bir eylemin o zamandan ÖNCE TAMAMLANMIŞ olacağı anlatılıyorsa [[q]]future perfect[[/q]] ([[q]]will have + V3[[/q]]) kullanılır ([[q]]\"By next year, I will have graduated\"[[/q]] = mezuniyet o zamandan önce bitmiş olacak)."}]}, {"heading": "Tetikleyici Kalıplar", "badge": "Hızlı Ayırt Etme", "body": [{"type": "text", "text": "[[q]]\"by the time + present simple cümlecik\"[[/q]] kalıbı YDS'nin klasik future perfect tetikleyicisidir; [[q]]\"at + belirli an\"[[/q]] ise future continuous'un işaretidir. İkisini karıştırmamak için kendine şunu sor: o anda eylem HALA mı oluyor (continuous) yoksa o ana kadar BİTMİŞ mi olacak (perfect)?"}]}], "examples": [{"sentence": "By the time the guests arrive, she will have finished cooking dinner.", "answer_word": "will have finished", "reasoning": "[[q]]\"by the time\"[[/q]] + present simple kalıbı, yemek pişirme eyleminin misafirler gelmeden ÖNCE tamamlanmış olacağını gösterir → doğru cevap future perfect [[right]]\"will have finished\"[[/right]]tir."}, {"sentence": "Don't call me at 8 PM, I will be having dinner with my family at that time.", "answer_word": "will be having", "reasoning": "[[q]]\"at that time\"[[/q]] (o saatte) ifadesi belirli bir anı işaret ediyor ve yemek yeme eyleminin o anda HALA SÜRECEĞİ anlatılıyor → doğru cevap future continuous [[right]]\"will be having\"[[/right]]dir, [[wrong]]future perfect[[/wrong]] burada yanlış olurdu çünkü eylemin bitmiş olması değil, o anda sürüyor olması vurgulanıyor."}, {"sentence": "This time next month, I will be relaxing on a beach in Antalya instead of sitting in this office.", "answer_word": "will be relaxing", "reasoning": "[[q]]\"this time next month\"[[/q]] belirli bir anı işaret ediyor ve o anda tatilde olma eyleminin HALA SÜRECEĞİ anlatılıyor → doğru cevap future continuous [[right]]\"will be relaxing\"[[/right]]dir."}, {"sentence": "By the end of this year, the company will have opened three new branches in different cities.", "answer_word": "will have opened", "reasoning": "[[q]]\"by the end of this year\"[[/q]] ifadesi, şubelerin açılma eyleminin o zamana kadar TAMAMLANMIŞ olacağını gösteriyor → doğru cevap future perfect [[right]]\"will have opened\"[[/right]]tir."}]}$tagbd$::jsonb WHERE id = '786b77cd-08ea-48c7-9669-7591666dc259';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Tam ezbersiz bir kural yoktur ama güçlü bir eğilim şudur: bazı fiiller SOMUT/DEVAM EDEN bir eylemi anlattığı için [[q]]-ing[[/q]] alır, bazıları ise GELECEĞE YÖNELİK bir niyeti anlattığı için [[q]]to-infinitive[[/q]] alır — üstelik bazı fiillerde hangisinin geldiğine göre ANLAM da değişir:", "items": [{"heading": "Genelde Gerund Alan Fiiller", "badge": "Somut / Devam Eden Eylem", "body": [{"type": "text", "text": "[[amber]]enjoy, avoid, finish, consider, suggest, admit, deny, practice, mind, imagine[[/amber]] gibi fiiller genelde SOMUT, DEVAM EDEN veya ZATEN YAPILAN bir eylemi anlattığı için [[ok]]-ing (gerund)[[/ok]] alır ([[q]]\"enjoy swimming\"[[/q]], [[q]]\"avoid making mistakes\"[[/q]])."}]}, {"heading": "Genelde to-infinitive Alan Fiiller", "badge": "Geleceğe Yönelik Niyet", "body": [{"type": "text", "text": "[[amber]]decide, plan, hope, promise, agree, offer, refuse, manage, afford, expect[[/amber]] gibi fiiller ise HENÜZ GERÇEKLEŞMEMİŞ, GELECEĞE YÖNELİK bir niyeti anlattığı için [[ok]]to-infinitive[[/ok]] alır ([[q]]\"decided to leave\"[[/q]], [[q]]\"hope to see you\"[[/q]])."}]}, {"heading": "Anlam Değiştiren Fiiller: remember / stop / forget", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[amber]]remember, forget, stop, try, regret[[/amber]] gibi fiillerde ANLAM DEĞİŞİR — YDS bu çiftleri özellikle sever:"}], "meaning_pairs": [[{"word": "remember doing", "meaning": "geçmişte yapmış olmayı HATIRLAMAK"}, {"word": "remember to do", "meaning": "yapılacak bir şeyi UNUTMAMAK", "variant": "wrong"}], [{"word": "stop doing", "meaning": "eylemin KENDİSİNİ durdurmak (örn. sigarayı bırakmak)"}, {"word": "stop to do", "meaning": "başka bir şey yapmak için DURMAK", "variant": "wrong"}]], "warning_text": "Bu fiillerden sonra -ing mi yoksa to-infinitive mi geldiğine göre cümlenin anlamı tamamen değişir, bu yüzden sadece fiile değil cümlenin anlamına da bakmak gerekir."}], "examples": [{"sentence": "I remember locking the door before leaving.", "answer_word": "locking", "reasoning": "Kapıyı kilitleme eyleminin GEÇMİŞTE gerçekleştiğini hatırlamak anlatılıyor → doğru cevap [[right]]\"locking\"[[/right]]tir."}, {"sentence": "I must remember to lock the door before I leave.", "answer_word": "to lock", "reasoning": "Burada henüz yapılmamış, hatırlanması gereken bir görev anlatıldığı için doğru cevap [[right]]\"to lock\"[[/right]]tur."}, {"sentence": "On his way home, he stopped to buy some bread.", "answer_word": "to buy", "reasoning": "Burada durma eyleminin AMACI ekmek almaktır (duruş + amaç) → doğru cevap [[right]]\"to buy\"[[/right]]dur."}, {"sentence": "He stopped smoking five years ago.", "answer_word": "smoking", "reasoning": "Burada sigara içme eyleminin kendisinin durdurulması anlatıldığı için doğru cevap [[right]]\"smoking\"[[/right]]dir — [[q]]\"stop to do\"[[/q]] ile [[q]]\"stop doing\"[[/q]] tamamen farklı anlamlar taşır."}, {"sentence": "They finally managed to finish the project despite the tight deadline.", "answer_word": "to finish", "reasoning": "[[q]]\"manage\"[[/q]] fiilinden sonra GELECEĞE yönelik bir niyet değil, zaten başarılmış somut bir sonucu anlattığı için to-infinitive alır → doğru cevap [[right]]\"to finish\"[[/right]]tir, \"manage\" kesinlikle -ing almaz."}, {"sentence": "I'll never forget seeing the northern lights for the first time — it was breathtaking.", "answer_word": "seeing", "reasoning": "Burada GEÇMİŞTE yaşanmış bir anıyı hatırlamak anlatıldığı için doğru cevap [[right]]\"seeing\"[[/right]]dir; [[q]]\"forget to do\"[[/q]] (yapılacak bir görevi unutmak) burada anlamca uymaz çünkü cümle geçmiş bir deneyimden bahsediyor."}]}$tagbd$::jsonb WHERE id = '319a9471-5479-4d76-adb7-da73d58a2129';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Cümlede bir gelecek zaman belirteci VARSA ve kişinin ÖNCEDEN DÜZENLEDİĞİ, takvime bağlı bir eylem anlatılıyorsa [[q]]will[[/q]] değil [[q]]present continuous[[/q]] doğru cevaptır; cümle o anda alınan bir karar ya da belirsiz bir tahminse [[q]]will[[/q]] kullanılır:", "items": [{"heading": "Önceden Ayarlanmış Plan → Present Continuous", "badge": "am/is/are + -ing", "body": [{"type": "text", "text": "Bir cümlede gelecek zaman belirteci ([[amber]]tomorrow, next week, at 5 p.m. on Friday[[/amber]]) VARSA ve cümle kişinin ÖNCEDEN DÜZENLEDİĞİ, takvime/plana bağlı bir eylemden bahsediyorsa (bir buluşma, bir uçuş, bir toplantı), [[bad]]will[[/bad]] değil [[ok]]present continuous[[/ok]] ([[q]]am/is/are + -ing[[/q]]) doğru cevaptır — çünkü bu, sadece bir tahmin değil, zaten ayarlanmış somut bir düzenlemedir."}]}, {"heading": "Güçlü İşaret: Randevu Fiili + Kesin Detay", "badge": "arrange / meet / fly / leave", "body": [{"type": "text", "text": "Cümlede [[amber]]\"arrange, meet, fly, leave\"[[/amber]] gibi randevu/seyahat bildiren fiiller ve kesin bir zaman/yer detayı (hangi uçakla, saat kaçta, kiminle) bir aradaysa bu, present continuous'un en güçlü işaretidir."}]}, {"heading": "will: Anlık Karar veya Belirsiz Tahmin", "badge": "Karşıt Durum", "body": [{"type": "text", "text": "Buna karşılık cümle o anda alınan bir karar veya belirsiz bir tahminse ([[q]]\"I think it will rain\"[[/q]]) [[ok]]will[[/ok]] doğru kalır."}]}], "examples": [{"sentence": "I can't make it to the meeting on Thursday — I am meeting my parents at the airport that afternoon.", "answer_word": "am meeting", "reasoning": "Burada önceden planlanmış, saati belli bir havaalanı karşılaması anlatıldığı için doğru cevap [[right]]\"am meeting\"[[/right]]dir; [[wrong]]\"will meet\"[[/wrong]] o anda alınan bir karar izlenimi verir ve önceden ayarlanmış bir plana uymaz."}, {"sentence": "Don't worry about the weather forecast — I'm sure it will be fine by the weekend.", "answer_word": "will be", "reasoning": "Burada kesin bir düzenleme değil, konuşmacının o anki TAHMİNİ anlatıldığı için doğru cevap [[right]]\"will be\"[[/right]]dir; [[wrong]]\"am being\"[[/wrong]] burada hem anlamca hem yapıca yanlıştır çünkü hava durumu insanın planladığı bir şey değildir."}, {"sentence": "I can't join you for lunch on Monday — I am meeting a client in Ankara that whole day.", "answer_word": "am meeting", "reasoning": "Belirli bir gün ve önceden ayarlanmış bir iş randevusu anlatıldığı için doğru cevap present continuous [[right]]\"am meeting\"[[/right]]dir; [[wrong]]\"will meet\"[[/wrong]] burada o anda alınan bir karar izlenimi verir, önceden ayarlanmış somut bir plana uymaz."}, {"sentence": "Judging by how dark those clouds look, I think we'll need umbrellas later today.", "answer_word": "think", "reasoning": "Burada somut bir düzenleme değil, gözlemden yola çıkan kişisel bir TAHMİN/görüş anlatıldığı için doğru cevap [[q]]\"think\"[[/q]] fiiliyle kurulan [[right]]\"will need\"[[/right]]dir; [[wrong]]\"am needing\"[[/wrong]] durum fiili olan \"need\"in -ing alamayacağı için zaten yanlıştır, present continuous bu cümlede hiç uygun değildir."}]}$tagbd$::jsonb WHERE id = 'd3da5634-4746-4bc3-9ef4-dfc109cbde5d';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Birçok sıfat ve fiil, belirli bir edatla SABİT bir kalıp oluşturur ve bu kalıp Türkçedeki edat mantığıyla ÖRTÜŞMEZ, bu yüzden anlamdan değil [[dark]]EZBERDEN[[/dark]] çözülmelidir:", "items": [{"heading": "Sabit Sıfat + Edat Kalıpları", "badge": "Ezbere Bilinmeli", "sub_rules": [{"condition": "[[q]]good[[/q]] sıfatından sonra sabit olarak:", "from": "good", "to": "at"}, {"condition": "[[q]]interested[[/q]] sıfatından sonra sabit olarak:", "from": "interested", "to": "in"}, {"condition": "[[q]]afraid[[/q]] sıfatından sonra sabit olarak:", "from": "afraid", "to": "of"}, {"condition": "[[q]]responsible[[/q]] sıfatından sonra sabit olarak:", "from": "responsible", "to": "for"}]}, {"heading": "Sabit Fiil + Edat Kalıpları", "badge": "Ezbere Bilinmeli", "sub_rules": [{"condition": "[[q]]depend[[/q]] fiilinden sonra sabit olarak:", "from": "depend", "to": "on"}, {"condition": "[[q]]insist[[/q]] fiilinden sonra sabit olarak:", "from": "insist", "to": "on"}, {"condition": "[[q]]succeed[[/q]] fiilinden sonra sabit olarak:", "from": "succeed", "to": "in"}, {"condition": "[[q]]apologize[[/q]] fiilinden sonra sabit olarak:", "from": "apologize", "to": "for"}]}, {"heading": "Türkçe Çeviriye Güvenme", "badge": "Sık Hata", "body": [{"type": "text", "text": "Bir boşlukta sıfat/fiil + edat kalıbı aranıyorsa, önce o sıfat/fiilin HANGİ EDATLA sabitlendiğini hatırlamak gerekir — Türkçe çeviriye güvenmek (ör. [[q]]\"ilgilenmek\"[[/q]] kelimesinin \"ile\" ekini [[bad]]\"with\"[[/bad]] olarak çevirmeye çalışmak, oysa doğrusu [[ok]]\"interested IN\"[[/ok]]dir) klasik bir hata kaynağıdır; bu kalıplar anlamdan değil [[dark]]EZBERDEN[[/dark]] çözülmelidir."}]}], "examples": [{"sentence": "She has always been extremely good at solving complex mathematical problems.", "answer_word": "at", "reasoning": "[[q]]\"good\"[[/q]] sıfatından sonra sabit olarak [[q]]\"at\"[[/q]] edatı gelir → doğru cevap [[right]]\"at\"[[/right]]tır."}, {"sentence": "The manager is directly responsible for any delays in the delivery schedule.", "answer_word": "for", "reasoning": "[[q]]\"responsible\"[[/q]] sıfatından sonra sabit olarak [[q]]\"for\"[[/q]] edatı gelir → doğru cevap [[right]]\"for\"[[/right]]dur, Türkçe \"sorumlu\" kelimesinden yola çıkarak başka bir edat (ör. [[wrong]]\"of\"[[/wrong]]) seçmek yanlış olur."}, {"sentence": "Despite strong objections from her colleagues, she insisted on handling the negotiations herself.", "answer_word": "on", "reasoning": "[[q]]\"insist\"[[/q]] fiilinden sonra sabit olarak [[q]]\"on\"[[/q]] edatı gelir → doğru cevap [[right]]\"on\"[[/right]]dur."}, {"sentence": "After weeks of persuasion, he finally succeeded in convincing the board to approve the budget increase.", "answer_word": "in", "reasoning": "[[q]]\"succeed\"[[/q]] fiilinden sonra sabit olarak [[q]]\"in\"[[/q]] edatı gelir → doğru cevap [[right]]\"in\"[[/right]]dir; Türkçe \"başarmak\" kelimesinden yola çıkarak [[wrong]]\"at\"[[/wrong]] ya da [[wrong]]\"to\"[[/wrong]] seçmek yaygın bir hata olur."}]}$tagbd$::jsonb WHERE id = 'd47ebfcc-b547-4ce1-89aa-3cc171d702aa';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]If[[/q]] normal bir koşulu anlatır, [[q]]unless[[/q]] ve [[q]]in case[[/q]] ise iki ayrı mantıkla çalışır:", "items": [{"heading": "If vs Unless: Aynı Anlam, Ters Kurulum", "badge": "Koşul", "body": [{"type": "text", "text": "[[q]]If[[/q]] normal bir koşulu anlatır (\"eğer X olursa Y olur\")."}, {"type": "text", "text": "[[q]]Unless[[/q]] ise [[q]]\"if...not\"[[/q]] ile [[dark]]AYNI[[/dark]] anlamı taşır, yani \"eğer X olmazsa\" demektir."}, {"type": "example_check", "correct": "Unless he apologizes, she won't forgive him", "wrong_note": "\"unless he doesn't apologize\" ÇİFT OLUMSUZLUK hatasıdır ve kesinlikle yanlıştır"}]}, {"heading": "In case: Koşul Değil, Tedbir", "badge": "Önlem", "body": [{"type": "text", "text": "[[q]]In case[[/q]] bambaşka bir mantık taşır: gerçekleşmesi KOŞUL olan bir şeyi değil, gerçekleşme İHTİMALİNE karşı ÖNCEDEN alınan bir [[dark]]TEDBİRİ[[/dark]] anlatır."}, {"type": "text", "text": "[[b]]\"Take an umbrella in case it rains\"[[/b]] → yağmur yağma ihtimaline karşı önlem al demektir, yağmur yağınca şemsiyeyi kullan demek DEĞİLDİR."}]}, {"heading": "Ayırt Etme Testi", "badge": "Karar Sorusu", "body": [{"type": "text", "text": "Bu üçünü ayırt etmenin anahtarı, cümlenin bir [[amber]]KOŞULU[[/amber]] mu yoksa bir [[amber]]ÖNLEMİ[[/amber]] mi anlattığını sormaktır."}]}], "examples": [{"sentence": "Unless you apologize to her, she won't forgive you for what you said.", "answer_word": "Unless", "reasoning": "Cümle [[b]]\"eğer özür dilemezsen\"[[/b]] anlamını taşıdığı için doğru cevap [[right]]\"Unless\"[[/right]]tır; [[wrong]]\"If\"[[/wrong]] kullanılsaydı fiilin olumsuz kalması gerekirdi (\"If you don't apologize\")."}, {"sentence": "Take a copy of the contract with you in case the client asks to see it during the meeting.", "answer_word": "in case", "reasoning": "Burada gerçekleşmesi kesin olmayan bir duruma karşı ÖNCEDEN alınan bir tedbir anlatıldığı için doğru cevap [[right]]\"in case\"[[/right]]tir; [[wrong]]\"if\"[[/wrong]] kullanılsaydı anlam \"müşteri isterse o an kopyasını al\" gibi mantıksız bir koşula dönüşürdü."}, {"sentence": "Unless the weather improves significantly by tomorrow morning, the outdoor concert will have to be cancelled.", "answer_word": "Unless", "reasoning": "Cümle [[b]]\"eğer hava düzelmezse\"[[/b]] anlamını taşıdığı için doğru cevap [[right]]\"Unless\"[[/right]]tır; [[wrong]]\"If\"[[/wrong]] kullanılsaydı fiilin olumsuz hâle getirilmesi gerekirdi (\"If the weather doesn't improve\")."}, {"sentence": "She always keeps a spare key with her neighbor in case she accidentally locks herself out of the house.", "answer_word": "in case", "reasoning": "Burada gerçekleşmesi kesin olmayan bir duruma karşı ÖNCEDEN alınmış bir tedbir anlatıldığı için doğru cevap [[right]]\"in case\"[[/right]]tir; [[wrong]]\"if\"[[/wrong]] kullanılsaydı cümle mantıksız bir koşula dönüşürdü, çünkü anahtar zaten o an için değil, olası bir durum için bırakılmıştır."}]}$tagbd$::jsonb WHERE id = '5c0b08d8-1c54-4866-9168-71ce502d9610';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]most[[/q]] ve [[q]]most of[[/q]] arasındaki seçim, ardından bir BELİRLEYİCİ olup olmadığına bakılarak yapılır:", "items": [{"heading": "\"most\" + Çıplak İsim", "badge": "Genel Çoğunluk", "body": [{"type": "text", "text": "[[q]]most[[/q]] ÇIPLAK bir çoğul/sayılamayan isimden önce gelirse genel bir çoğunluğu anlatır."}, {"type": "example_check", "correct": "Most students enjoy holidays", "wrong_note": "\"Most of students\" yanlıştır çünkü \"of\"tan sonra çıplak isim gelemez"}]}, {"heading": "\"most of\" + Belirleyici + İsim", "badge": "Belirli Grup", "body": [{"type": "text", "text": "[[q]]most of[[/q]] ise ardından MUTLAKA [[amber]]the/this/that/these/those/my/his[[/amber]] gibi bir belirleyici veya bir zamir ([[amber]]us/them/you[[/amber]]) gelir ve BELİRLİ, tanımlanmış bir grubun çoğunluğunu anlatır."}, {"type": "example_check", "correct": "Most of the students in this class study hard", "wrong_note": "sadece \"Most the students\" demek YANLIŞTIR, \"of\" atlanamaz"}]}, {"heading": "En Sık Tuzak: \"most the...\"", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Bir şıkta [[q]]most[[/q]] yazıp hemen ardından [[amber]]the/this/my[[/amber]] geliyorsa o şık [[dark]]KESİNLİKLE YANLIŞTIR[[/dark]], \"the\" her zaman \"of\"tan sonra gelir."}], "warning_text": "Doğrusu ya [[q]]most[[/q]] + çıplak isim ya da [[q]]most of[[/q]] + belirleyici + isimdir."}], "examples": [{"sentence": "Most people in this country speak at least two languages.", "answer_word": "Most", "reasoning": "Boşluktan sonra çıplak bir çoğul isim (\"people\") geliyor, belirleyici yok → doğru cevap [[right]]\"Most\"[[/right]]tur; [[wrong]]\"Most of\"[[/wrong]] burada yanlıştır çünkü ardından \"the/these\" gibi bir belirleyici gelmemiştir."}, {"sentence": "Most of the employees at this company have been working here for over five years.", "answer_word": "Most of", "reasoning": "Boşluktan sonra \"the employees\" (belirleyici + isim) geldiği için doğru cevap [[right]]\"Most of\"[[/right]]tur; sadece [[wrong]]\"Most\"[[/wrong]] kullanmak için \"the\" kelimesinin cümleden çıkarılması gerekirdi."}, {"sentence": "Most scientists agree that climate change is primarily driven by human activity.", "answer_word": "Most", "reasoning": "Boşluktan sonra ÇIPLAK bir çoğul isim (\"scientists\") geliyor, herhangi bir belirleyici (the/my/these) yok → doğru cevap [[right]]\"Most\"[[/right]]tur; [[wrong]]\"Most of\"[[/wrong]] burada yanlıştır çünkü \"of\"tan sonra mutlaka bir belirleyici gelmesi gerekir, çıplak bir isim gelemez."}, {"sentence": "Most of my colleagues were surprised by the sudden announcement of the merger.", "answer_word": "Most of", "reasoning": "Boşluktan sonra iyelik sıfatı + isim (\"my colleagues\") geldiği için doğru cevap [[right]]\"Most of\"[[/right]]tur; sadece [[wrong]]\"Most\"[[/wrong]] kullanmak için cümleden \"my\" kelimesinin çıkarılması gerekirdi, çünkü \"most\" doğrudan bir iyelik sıfatından önce gelemez."}]}$tagbd$::jsonb WHERE id = '15bc23dd-17f0-49c8-a390-74b369d7203a';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Geçmişteki yetenek anlatımında [[q]]could[[/q]] ile [[q]]was/were able to[[/q]] arasındaki seçim, yeteneğin GENEL mi yoksa TEK SEFERLİK mi olduğuna bağlıdır:", "items": [{"heading": "could: Genel Geçmiş Yetenek", "badge": "Süreklilik", "body": [{"type": "text", "text": "[[q]]could[[/q]]: geçmişte [[amber]]GENEL/SÜREKLİ[[/amber]] bir yeteneği anlatır."}, {"type": "example_check", "correct": "When I was young, I could run for hours", "wrong_note": "genel bir beceriyi anlatır, tek seferlik bir başarıyı değil"}]}, {"heading": "was/were able to: Tek Seferlik Başarı", "badge": "Özel Durum", "body": [{"type": "text", "text": "[[q]]was/were able to[[/q]]: geçmişte [[amber]]TEK SEFERLİK[[/amber]], belirli bir başarıyı anlatır."}, {"type": "example_check", "correct": "After hours of negotiation, they were able to reach an agreement", "wrong_note": "\"could\" kullanılması burada tipik bir yanlış şık tuzağıdır"}]}, {"heading": "Olumsuzda Ayrım Ortadan Kalkar", "body": [{"type": "text", "text": "Olumsuzda bu ayrım [[dark]]ORTADAN KALKAR[[/dark]]: [[q]]couldn't[[/q]] hem genel hem tek seferlik olumsuz yetenek için kullanılabilir (\"I couldn't solve the puzzle\" tek seferlik bir durum olsa bile doğrudur)."}]}], "examples": [{"sentence": "Despite the heavy traffic, she was able to arrive at the meeting on time.", "answer_word": "was able to", "reasoning": "Tek seferlik, belirli bir başarı anlatıldığı için doğru cevap [[right]]\"was able to\"[[/right]]dur; [[wrong]]\"could\"[[/wrong]] burada yanlıştır."}, {"sentence": "My grandfather could speak four languages fluently.", "answer_word": "could", "reasoning": "Burada geçmişte genel, sürekli bir yetenek anlatıldığı için doğru cevap [[right]]\"could\"[[/right]]dur. Ama \"Even though the exam was very difficult, she was able to finish it within the time limit.\" cümlesinde tek seferlik, belirli bir başarı anlatıldığı için doğru cevap [[wrong]]\"was able to\"[[/wrong]]dur, \"could\" değil."}, {"sentence": "Although the lock was rusted, the locksmith was able to open the door within minutes.", "answer_word": "was able to", "reasoning": "Tek seferlik, belirli bir başarı anlatıldığı için doğru cevap [[right]]\"was able to\"[[/right]]dur; [[wrong]]\"could\"[[/wrong]] burada yanlıştır çünkü genel bir yeteneği değil, o anki özel bir başarıyı anlatır."}, {"sentence": "As a child, my uncle could hold his breath underwater for almost two minutes.", "answer_word": "could", "reasoning": "Burada geçmişte genel, sürekli bir yetenek anlatıldığı için doğru cevap [[right]]\"could\"[[/right]]dur; [[wrong]]\"was able to\"[[/wrong]] burada da kabul edilebilir olsa da, tekrarlanan/genel bir çocukluk becerisi anlatıldığı için \"could\" daha doğal ve beklenen cevaptır."}]}$tagbd$::jsonb WHERE id = 'b21c688a-8fb8-4768-a0f5-e3c1b588e638';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Modallarla çıkarım yaparken önce kesinlik derecesine, sonra da zamana (şimdi mi geçmiş mi) bakılır:", "items": [{"heading": "Şimdiki Çıkarım Skalası", "badge": "Kesinlik Sırası", "body": [{"type": "text", "text": "Şimdiki/genel çıkarımlarda kesinlik derecesine göre sırala: [[q]]must[[/q]] (çok güçlü çıkarım, \"...olmalı\") > [[q]]should/ought to[[/q]] (beklenti) > [[q]]can[[/q]] (genel/teorik olasılık) > [[q]]may[[/q]] (orta, ~%50) > [[q]]might/could[[/q]] (zayıf olasılık)."}]}, {"heading": "Olumsuz Kesinlik: can't / couldn't", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Olumsuz kesinlikte [[ok]]\"can't/couldn't\"[[/ok]] kullanılır, [[bad]]\"must not\"[[/bad]] DEĞİL — bu en sık karıştırılan noktadır."}], "meaning_pairs": [[{"word": "can't / couldn't", "meaning": "kesinlikle olamaz (olumsuz çıkarım)"}, {"word": "must not", "meaning": "yasak (tamamen farklı bir anlam)", "variant": "wrong"}]], "warning_text": "\"He can't be at home, I just saw him at work.\" cümlesinde [[wrong]]\"must not\"[[/wrong]] kullanmak anlamı yasaklamaya çevirir ve yanlıştır."}, {"heading": "Geçmişe Yönelik Çıkarım: Modal + HAVE + V3", "badge": "Modal Perfect", "body": [{"type": "text", "text": "[[q]]must have V3[[/q]] → güçlü geçmiş çıkarım (\"...mış olmalı\")."}, {"type": "text", "text": "[[q]]may/might have V3[[/q]] → zayıf geçmiş çıkarım (\"...mış olabilir\")."}, {"type": "text", "text": "[[q]]could have V3[[/q]] → yapılabilirdi ama olmadı."}, {"type": "text", "text": "[[q]]should have V3[[/q]] → yapılmalıydı, pişmanlık."}, {"type": "text", "text": "[[q]]needn't have V3[[/q]] → yapıldı ama gerekmemiş."}]}, {"heading": "Zaman İpucu", "body": [{"type": "text", "text": "Cümlede [[amber]]\"yesterday/last week/by then\"[[/amber]] gibi bir geçmiş zaman referansı varsa ve şıklarda modal yapılar varsa, aranan kalıp büyük ihtimalle [[b]]modal perfect[[/b]]tir."}]}], "examples": [{"sentence": "He knows every detail about the incident. He must be the one who witnessed it.", "answer_word": "must", "reasoning": "Kesin bir kanıt var (her detayı biliyor) için doğru cevap [[right]]\"must\"[[/right]]tur (güçlü şimdiki çıkarım). Benzer şekilde geçmişe yönelik güçlü bir çıkarımda [[q]]must have[[/q]] kullanılır: \"The lights are off and the car is gone. She must have left already.\""}, {"sentence": "The lights in her office are off and her car isn't in the parking lot. She must have gone home early.", "answer_word": "must have", "reasoning": "Kanıtlar güçlü bir çıkarıma işaret ediyor (ışıklar kapalı, araba yok) → doğru cevap [[right]]\"must have\"[[/right]]dir. Ama kesin bir kanıt olmadığında (\"I'm not sure, but she might be at a meeting right now\") zayıf bir olasılık anlatılır ve doğru cevap [[wrong]]\"might/could\"[[/wrong]] olur, \"must\" değil."}, {"sentence": "She says she has never been to Paris, but these photos were clearly taken right in front of the Eiffel Tower — she can't be telling the truth.", "answer_word": "can't", "reasoning": "Kanıtlar (fotoğraflar) açık bir ÇELİŞKİYİ gösterdiği için olumsuz kesin bir çıkarım gerekir → doğru cevap [[right]]\"can't\"[[/right]]tır; [[wrong]]\"must not\"[[/wrong]] burada yanlıştır çünkü olumsuz kesinlik için İngilizce'de \"can't/couldn't\" kullanılır, \"must not\" farklı bir anlam (yasaklama) taşır."}, {"sentence": "I should have brought my umbrella — the forecast clearly said it would rain all day, yet I left it at home and got soaked.", "answer_word": "should have brought", "reasoning": "Yağmur yağacağı önceden BİLİNDİĞİ halde şemsiye alınmaması bir PİŞMANLIK anlatıldığı için doğru cevap [[right]]\"should have brought\"[[/right]]tur; [[wrong]]\"needn't have brought\"[[/wrong]] yanlış olurdu çünkü o yapı GEREKSİZ YERE yapılmış bir eylemi anlatır, burada ise tam tersine yapılmamış ama yapılması gereken bir eylemden bahsedilmektedir."}]}$tagbd$::jsonb WHERE id = 'a3d3a6db-14a1-4e17-a046-0dc42781ce1e';
